if os.path.exists(test_image_path):
    test_img = cv2.imread(test_image_path)

    if test_img is None:
        raise ValueError("Image failed to load")

    print(f"Image loaded: {test_img.shape[1]}x{test_img.shape[0]} pixels\n")

    # Run detection
    detections = detect_people(
        test_img,
        model_pipeline,
        step_size=STEP_SIZE,
        min_confidence=3.8,
        nms_threshold=0.25
    )

    # Copy image for drawing
    result = test_img.copy()

    # Draw bounding boxes
    for det in detections:
        x, y, w, h, score = det
        x, y, w, h = int(x), int(y), int(w), int(h)

        cv2.rectangle(
            result,
            (x, y),
            (x + w, y + h),
            (0, 255, 0),
            2
        )

        cv2.putText(
            result,
            f"{score:.2f}",
            (x, max(y - 5, 10)),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.5,
            (0, 255, 0),
            1
        )

    # Crowd info
    num_people = len(detections)
    h_img, w_img = result.shape[:2]
    density = (num_people / (w_img * h_img)) * 100000

    if density < 5:
        crowd_level = "Low"
    elif density < 15:
        crowd_level = "Medium"
    elif density < 30:
        crowd_level = "High"
    else:
        crowd_level = "Very High"

    cv2.putText(result, f"People: {num_people}", (10, 30),
                cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)
    cv2.putText(result, f"Crowd: {crowd_level}", (10, 65),
                cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)
    cv2.putText(result, f"Density: {density:.2f}", (10, 100),
                cv2.FONT_HERSHEY_SIMPLEX, 1, (0, 255, 0), 2)

    plt.figure(figsize=(14, 9))
    plt.imshow(cv2.cvtColor(result, cv2.COLOR_BGR2RGB))
    plt.title("HOG + SIFT Crowd Detection")
    plt.axis("off")
    plt.show()

